import{_ as t,o,c as a,a0 as i}from"./chunks/framework.BDx3ik-m.js";const p=JSON.parse('{"title":"EPIC 38: Communications Code Quality — Removed Endpoints, URL Fixes, JSDoc, Rate Limits, Tests","description":"","frontmatter":{},"headers":[],"relativePath":"epics/EPIC_38_COMMUNICATIONS_CODE_QUALITY.md","filePath":"epics/EPIC_38_COMMUNICATIONS_CODE_QUALITY.md"}'),d={name:"epics/EPIC_38_COMMUNICATIONS_CODE_QUALITY.md"};function r(s,e,n,c,l,m){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="epic-38-communications-code-quality-—-removed-endpoints-url-fixes-jsdoc-rate-limits-tests" tabindex="-1">EPIC 38: Communications Code Quality — Removed Endpoints, URL Fixes, JSDoc, Rate Limits, Tests <a class="header-anchor" href="#epic-38-communications-code-quality-—-removed-endpoints-url-fixes-jsdoc-rate-limits-tests" aria-label="Permalink to &quot;EPIC 38: Communications Code Quality — Removed Endpoints, URL Fixes, JSDoc, Rate Limits, Tests&quot;">​</a></h1><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Epic</strong></td><td>38</td></tr><tr><td><strong>Module</strong></td><td>communications (<code>09-communications.yaml</code>)</td></tr><tr><td><strong>Priority</strong></td><td>High</td></tr><tr><td><strong>Target SDK Version</strong></td><td>v2.7.x</td></tr><tr><td><strong>Status</strong></td><td>COMPLETED</td></tr><tr><td><strong>Backlog Task</strong></td><td>task-38</td></tr><tr><td><strong>Depends On</strong></td><td>None</td></tr><tr><td><strong>Source</strong></td><td>February 2026 Swagger Audit</td></tr><tr><td><strong>Related Stories</strong></td><td>4.2 (Communications Customer Engagement)</td></tr></tbody></table><hr><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>The February 2026 swagger audit identified significant code quality gaps in the 26-method communications module. While the module has a QA score of 98/100 from the original manual implementation review, the auto-generated module has critical issues:</p><ol><li><p><strong>6 Removed Endpoints Not Marked</strong>: 6 SDK methods call endpoints no longer in the swagger but have no <code>@deprecated</code> tags or runtime warnings.</p></li><li><p><strong>3 Base URL Mismatches</strong>: 3 chat methods use the wrong domain (<code>api.wildberries.ru</code> instead of <code>buyer-chat-api.wildberries.ru</code>).</p></li><li><p><strong>26 JSDoc @example Bug</strong>: All 26 methods reference <code>sdk.general.*</code> instead of <code>sdk.communications.*</code>. Copy-paste from JSDoc fails at runtime.</p></li><li><p><strong>26 Rate Limit Keys Not Wired</strong>: 26 rate limit config entries exist in <code>src/config/communications-rate-limits.ts</code> but zero methods pass <code>rateLimitKey</code> to BaseClient. Rate limits are defined but never enforced.</p></li><li><p><strong>0 Tests</strong>: No unit tests or integration tests exist for the auto-generated module. The 88 tests referenced in QA gate 4.2 were for a different, manually-written implementation.</p></li></ol><hr><h2 id="detailed-gap-analysis" tabindex="-1">Detailed Gap Analysis <a class="header-anchor" href="#detailed-gap-analysis" aria-label="Permalink to &quot;Detailed Gap Analysis&quot;">​</a></h2><h3 id="gap-1-removed-endpoints-6-methods" tabindex="-1">Gap 1: Removed Endpoints (6 methods) <a class="header-anchor" href="#gap-1-removed-endpoints-6-methods" aria-label="Permalink to &quot;Gap 1: Removed Endpoints (6 methods)&quot;">​</a></h3><p>The following 6 endpoints have been removed from the swagger but still exist in the SDK:</p><table tabindex="0"><thead><tr><th>#</th><th>Removed Endpoint</th><th>SDK Method</th><th>Reason</th></tr></thead><tbody><tr><td>1</td><td><code>GET /api/v1/supplier-valuations</code></td><td><code>supplierValuations()</code></td><td>Endpoint removed from Otzyvy tag</td></tr><tr><td>2</td><td><code>POST /api/v1/feedbacks/actions</code></td><td><code>createFeedbacksAction()</code></td><td>Endpoint removed from Otzyvy tag</td></tr><tr><td>3</td><td><code>GET /api/v1/templates</code></td><td><code>templates()</code></td><td>Entire &quot;Shablony otvetov&quot; tag removed</td></tr><tr><td>4</td><td><code>POST /api/v1/templates</code></td><td><code>createTemplate()</code></td><td>Entire &quot;Shablony otvetov&quot; tag removed</td></tr><tr><td>5</td><td><code>PATCH /api/v1/templates</code></td><td><code>updateTemplate()</code></td><td>Entire &quot;Shablony otvetov&quot; tag removed</td></tr><tr><td>6</td><td><code>DELETE /api/v1/templates</code></td><td><code>deleteTemplate()</code></td><td>Entire &quot;Shablony otvetov&quot; tag removed</td></tr></tbody></table><p><strong>Required changes per method</strong>:</p><ol><li>Add <code>@deprecated</code> JSDoc tag with clear removal notice</li><li>Add <code>console.warn()</code> on first invocation using a static flag per method (warn-once pattern)</li><li>Method must continue to function for backward compatibility</li></ol><h3 id="gap-2-base-url-mismatches-3-methods" tabindex="-1">Gap 2: Base URL Mismatches (3 methods) <a class="header-anchor" href="#gap-2-base-url-mismatches-3-methods" aria-label="Permalink to &quot;Gap 2: Base URL Mismatches (3 methods)&quot;">​</a></h3><p>3 chat methods use <code>api.wildberries.ru</code> but the swagger specifies <code>buyer-chat-api.wildberries.ru</code>:</p><table tabindex="0"><thead><tr><th>#</th><th>SDK Method</th><th>Current URL</th><th>Correct URL</th></tr></thead><tbody><tr><td>1</td><td><code>getSellerEvents()</code></td><td><code>api.wildberries.ru</code></td><td><code>buyer-chat-api.wildberries.ru</code></td></tr><tr><td>2</td><td><code>createSellerMessage()</code></td><td><code>api.wildberries.ru</code></td><td><code>buyer-chat-api.wildberries.ru</code></td></tr><tr><td>3</td><td><code>getSellerDownload()</code></td><td><code>api.wildberries.ru</code></td><td><code>buyer-chat-api.wildberries.ru</code></td></tr></tbody></table><h3 id="gap-3-jsdoc-example-bug-26-methods" tabindex="-1">Gap 3: JSDoc @example Bug (26 methods) <a class="header-anchor" href="#gap-3-jsdoc-example-bug-26-methods" aria-label="Permalink to &quot;Gap 3: JSDoc @example Bug (26 methods)&quot;">​</a></h3><p>All 26 methods have <code>@example</code> blocks referencing <code>sdk.general.*</code> instead of <code>sdk.communications.*</code>. This is the same code generation template bug found in other modules (promotion: 42, in-store-pickup: 16, orders-fbw: 8).</p><p><strong>Fix</strong>: Replace all 26 occurrences of <code>sdk.general.</code> with <code>sdk.communications.</code> in <code>@example</code> blocks.</p><h3 id="gap-4-rate-limit-keys-not-wired-26-methods" tabindex="-1">Gap 4: Rate Limit Keys Not Wired (26 methods) <a class="header-anchor" href="#gap-4-rate-limit-keys-not-wired-26-methods" aria-label="Permalink to &quot;Gap 4: Rate Limit Keys Not Wired (26 methods)&quot;">​</a></h3><p>The file <code>src/config/communications-rate-limits.ts</code> defines 26 rate limit entries across 3 tiers:</p><ul><li><strong>Tier 1</strong>: 180 req/min (20 entries for Questions/Feedbacks/Templates)</li><li><strong>Tier 2</strong>: 60 req/min (4 entries for Chat)</li><li><strong>Tier 3</strong>: 20 req/min (2 entries for Returns)</li></ul><p>None of the 26 module methods pass <code>rateLimitKey</code> to BaseClient. This means rate limits are defined but never enforced at runtime, putting users at risk of 429 errors and potential API blocks.</p><p><strong>Fix</strong>: Add <code>rateLimitKey</code> option to all 26 BaseClient calls using the config keys from <code>communications-rate-limits.ts</code>.</p><h3 id="gap-5-missing-tests" tabindex="-1">Gap 5: Missing Tests <a class="header-anchor" href="#gap-5-missing-tests" aria-label="Permalink to &quot;Gap 5: Missing Tests&quot;">​</a></h3><p>No unit tests or integration tests exist for the auto-generated communications module. The 88 tests referenced in QA gate 4.2 were for a different, manually-written implementation.</p><p><strong>Fix</strong>: Create unit tests for all 20 active methods and 6 deprecation tests. Create integration tests with MSW for core happy paths.</p><hr><h2 id="implementation-approach" tabindex="-1">Implementation Approach <a class="header-anchor" href="#implementation-approach" aria-label="Permalink to &quot;Implementation Approach&quot;">​</a></h2><h3 id="step-1-fix-jsdoc-example-blocks" tabindex="-1">Step 1: Fix JSDoc @example Blocks <a class="header-anchor" href="#step-1-fix-jsdoc-example-blocks" aria-label="Permalink to &quot;Step 1: Fix JSDoc @example Blocks&quot;">​</a></h3><p>Replace all 26 occurrences of <code>sdk.general.</code> with <code>sdk.communications.</code> in <code>src/modules/communications/index.ts</code>.</p><h3 id="step-2-fix-3-base-url-mismatches" tabindex="-1">Step 2: Fix 3 Base URL Mismatches <a class="header-anchor" href="#step-2-fix-3-base-url-mismatches" aria-label="Permalink to &quot;Step 2: Fix 3 Base URL Mismatches&quot;">​</a></h3><p>Update the 3 chat methods (<code>getSellerEvents</code>, <code>createSellerMessage</code>, <code>getSellerDownload</code>) to use <code>buyer-chat-api.wildberries.ru</code> instead of <code>api.wildberries.ru</code>.</p><h3 id="step-3-mark-6-removed-endpoint-methods" tabindex="-1">Step 3: Mark 6 Removed Endpoint Methods <a class="header-anchor" href="#step-3-mark-6-removed-endpoint-methods" aria-label="Permalink to &quot;Step 3: Mark 6 Removed Endpoint Methods&quot;">​</a></h3><p>Add <code>@deprecated</code> JSDoc tag and <code>console.warn()</code> (warn-once pattern) to all 6 removed methods. Group related static flags to avoid excessive class-level properties.</p><h3 id="step-4-wire-rate-limit-keys" tabindex="-1">Step 4: Wire Rate Limit Keys <a class="header-anchor" href="#step-4-wire-rate-limit-keys" aria-label="Permalink to &quot;Step 4: Wire Rate Limit Keys&quot;">​</a></h3><p>Add <code>rateLimitKey</code> option to all 26 BaseClient calls using the config keys from <code>communications-rate-limits.ts</code>.</p><h3 id="step-5-add-new-rate-limit-entries" tabindex="-1">Step 5: Add New Rate Limit Entries <a class="header-anchor" href="#step-5-add-new-rate-limit-entries" aria-label="Permalink to &quot;Step 5: Add New Rate Limit Entries&quot;">​</a></h3><p>Add 5 new rate limit entries for EPIC 37 Pinned Reviews endpoints (total ~31).</p><h3 id="step-6-create-unit-tests" tabindex="-1">Step 6: Create Unit Tests <a class="header-anchor" href="#step-6-create-unit-tests" aria-label="Permalink to &quot;Step 6: Create Unit Tests&quot;">​</a></h3><p>Create <code>tests/unit/modules/communications.test.ts</code> from scratch with:</p><ul><li>Tests for all 20 active methods (rateLimitKey assertions, correct URL, correct HTTP method)</li><li>6 deprecation warning tests for removed endpoint methods</li></ul><h3 id="step-7-create-integration-tests" tabindex="-1">Step 7: Create Integration Tests <a class="header-anchor" href="#step-7-create-integration-tests" aria-label="Permalink to &quot;Step 7: Create Integration Tests&quot;">​</a></h3><p>Create <code>tests/integration/communications.integration.test.ts</code> from scratch with MSW handlers for core happy paths.</p><h3 id="step-8-verify-build-and-lint" tabindex="-1">Step 8: Verify Build and Lint <a class="header-anchor" href="#step-8-verify-build-and-lint" aria-label="Permalink to &quot;Step 8: Verify Build and Lint&quot;">​</a></h3><p>Run <code>npx tsc --noEmit</code> and <code>npm run lint</code> to ensure zero errors.</p><hr><h2 id="files-to-modify" tabindex="-1">Files to Modify <a class="header-anchor" href="#files-to-modify" aria-label="Permalink to &quot;Files to Modify&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Changes</th><th>Estimated Effort</th></tr></thead><tbody><tr><td><code>src/modules/communications/index.ts</code></td><td>Fix 26 @example blocks, fix 3 URLs, add 6 @deprecated tags + console.warn, wire 26 rateLimitKeys</td><td>High</td></tr><tr><td><code>src/config/communications-rate-limits.ts</code></td><td>Add 5 new entries for EPIC 37 Pinned Reviews endpoints</td><td>Low</td></tr><tr><td><code>tests/unit/modules/communications.test.ts</code></td><td>Create from scratch, ~26 method tests + 6 deprecation tests</td><td>High</td></tr><tr><td><code>tests/integration/communications.integration.test.ts</code></td><td>Create from scratch with MSW handlers</td><td>Medium</td></tr></tbody></table><hr><h2 id="risk-assessment" tabindex="-1">Risk Assessment <a class="header-anchor" href="#risk-assessment" aria-label="Permalink to &quot;Risk Assessment&quot;">​</a></h2><p><strong>Overall Risk</strong>: MEDIUM</p><table tabindex="0"><thead><tr><th>Risk</th><th>Likelihood</th><th>Impact</th><th>Mitigation</th></tr></thead><tbody><tr><td>URL changes break existing integrations</td><td>Medium</td><td>High</td><td>Document breaking change; correct URLs match swagger</td></tr><tr><td>Deprecated warnings break CI</td><td>Low</td><td>Medium</td><td>Use warn-once pattern; mock console.warn in tests</td></tr><tr><td>Rate limit wiring changes behavior</td><td>Low</td><td>Medium</td><td>Prevents 429 errors; correct per swagger</td></tr><tr><td>Many changes to one file</td><td>Medium</td><td>Medium</td><td>Careful testing; all changes are additive or fixes</td></tr></tbody></table><hr><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>[x] All 6 removed methods marked with <code>@deprecated</code> JSDoc tag and <code>console.warn</code> on first call</li><li>[x] All 3 base URL mismatches fixed (<code>buyer-chat-api.wildberries.ru</code>)</li><li>[x] All 26 JSDoc <code>@example</code> blocks reference <code>sdk.communications.*</code> (not <code>sdk.general.*</code>)</li><li>[x] All 26 methods pass correct <code>rateLimitKey</code> from communications-rate-limits config to BaseClient</li><li>[x] Rate limit config updated with 5 new entries for EPIC 37 endpoints (total 31)</li><li>[x] Unit tests for 20 active methods + 6 deprecated methods created and passing (44 total)</li><li>[ ] Integration tests for core happy paths created and passing (skipped - MSW v2.x localStorage issue)</li><li>[x] <code>npx tsc --noEmit</code> exits 0</li><li>[x] <code>npm run lint</code> exits 0</li></ul><hr><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Path</th></tr></thead><tbody><tr><td>Swagger spec</td><td><code>wildberries_api_doc/09-communications.yaml</code></td></tr><tr><td>Swagger shards</td><td><code>wildberries_api_doc/09-communications/</code> (5 shards)</td></tr><tr><td>Module source</td><td><code>src/modules/communications/index.ts</code> (1211 lines, 31 methods)</td></tr><tr><td>Rate limit config</td><td><code>src/config/communications-rate-limits.ts</code> (31 entries)</td></tr><tr><td>Types</td><td><code>src/types/communications.types.ts</code></td></tr><tr><td>Unit tests</td><td><code>tests/unit/modules/communications.test.ts</code> (44 tests)</td></tr><tr><td>Integration tests</td><td>Skipped (MSW v2.x localStorage issue)</td></tr><tr><td>Story 4.2</td><td><code>docs/stories/4.2.communications-customer-engagement.md</code></td></tr><tr><td>QA Gate 4.2</td><td><code>docs/qa/gates/4.2-communications-customer-engagement.yml</code></td></tr><tr><td>EPIC 36 (types)</td><td><code>docs/epics/EPIC_36_COMMUNICATIONS_TYPE_EXPANSION.md</code></td></tr><tr><td>EPIC 37 (new endpoints)</td><td><code>docs/epics/EPIC_37_COMMUNICATIONS_NEW_ENDPOINTS.md</code></td></tr><tr><td>Backlog task</td><td><code>backlog/tasks/task-38</code></td></tr></tbody></table><hr><h2 id="implementation-notes-completed-2026-02-06" tabindex="-1">Implementation Notes (Completed 2026-02-06) <a class="header-anchor" href="#implementation-notes-completed-2026-02-06" aria-label="Permalink to &quot;Implementation Notes (Completed 2026-02-06)&quot;">​</a></h2><h3 id="code-quality-fixes" tabindex="-1">Code Quality Fixes <a class="header-anchor" href="#code-quality-fixes" aria-label="Permalink to &quot;Code Quality Fixes&quot;">​</a></h3><ol><li><p><strong>6 Deprecated Methods</strong> - @deprecated JSDoc + console.warn (warn-once pattern):</p><ul><li>supplierValuations, createFeedbacksAction</li><li>templates, createTemplate, updateTemplate, deleteTemplate</li></ul></li><li><p><strong>3 Base URL Fixes</strong>:</p><ul><li>getSellerEvents: api.wildberries.ru → buyer-chat-api.wildberries.ru</li><li>createSellerMessage: api.wildberries.ru → buyer-chat-api.wildberries.ru</li><li>getSellerDownload: api.wildberries.ru → buyer-chat-api.wildberries.ru</li></ul></li><li><p><strong>26 JSDoc @example Fixes</strong>: All changed from sdk.general.* to sdk.communications.*</p></li><li><p><strong>31 rateLimitKey Wired</strong>: All 26 existing + 5 new Pinned Reviews methods</p></li><li><p><strong>5 Rate Limit Config Entries Added</strong> for Pinned Reviews</p></li></ol><h3 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h3><ul><li>44 unit tests created (was 0)</li><li>9 tests for deprecated methods with warning verification</li><li>12 tests for Pinned Reviews</li><li>23 tests for core methods</li><li>TDD tests: 4/4 passed</li></ul><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><ul><li>MSW integration tests skipped due to MSW v2.x localStorage compatibility issue</li><li>Parameter updates for updateClaim/createSellerMessage deferred to future task</li><li>Named types migration deferred to future task</li></ul>',69)])])}const u=t(d,[["render",r]]);export{p as __pageData,u as default};
